products=[
('calling','Browser Calling','Your business conversations. One browser.','Make outgoing calls without adding another desktop application to your day. Keep the dialer alongside the details that make each conversation useful.', [('A clearer calling workflow','Choose a contact, check the number, then place the call from the Dialnytics dialer.',['Incoming and outgoing calling','Dedicated caller ID','Call activity in your history']),('Built around your team','A microphone, a reliable connection and an active account are the starting point. Test your headset and browser permissions before a busy session.',['Review the browser guide','Keep customer details close','Use your selected country plan'])]),
('business-numbers','Business Numbers','Give every conversation a recognisable number.','Choose a country plan and request a dedicated caller ID. Our team confirms number availability and any documents needed before activation.', [('Choose your market','USA, Canada, UK, Australia and Japan plans are available. European local numbers and custom destination combinations are quoted individually.',['Country-specific plans','Dedicated caller ID included','Number preference collected with your request']),('Know what is being assigned','A preference is not a number reservation. Exact number type and availability are confirmed by the team before payment.',['No automatic number purchase on this website','No invented number guarantees','Existing users sign in to the separate dialer'])]),
('incoming-calls','Incoming Calls','Be there when customers call back.','Receive calls on your assigned business number in the Dialnytics dialer, alongside your outgoing activity.', [('One view of your conversations','See available caller information, answer the call and review your call history afterwards.',['Incoming calling included','Caller information where supplied','Incoming and outgoing history']),('Set expectations clearly','Keep the dialer connected and microphone access enabled when expecting calls. If you miss one, the caller can leave a voicemail that you can play back in the dialer.',['Check connectivity before a shift','Test your assigned number','Voicemail included in every plan'])]),
('call-recording','Call Recording','Keep the conversation, not just the outcome.','Call recording is an optional add-on, priced per user per month. Record only when the required notices and permissions are in place.', [('Add it to the users who need it','Choose the Call recording add-on with your plan. Recordings appear in the dialer, where you can play them back, download them or delete them.',['Optional paid add-on, see Pricing','Recording controls in the dialer','Play back, download or delete recordings']),('Use recordings responsibly','Recording is not the same as consent. Confirm the rules that apply to the participants and your business, and avoid recording unnecessary sensitive information.',['Tell participants where required','Limit access to authorised staff','Confirm retention and storage arrangements before activation'])]),
('campaigns','Power Dialer','Turn a lead list into a focused calling session.','Build a queue from selected CRM leads, move through eligible numbers and keep notes with each queue call.', [('Work through the right leads','Choose leads rather than dial every imported record. The calling workflow checks lead consent and Do Not Call status.',['Selected-lead queues','Start, pause, continue and skip controls','Call notes and outcomes']),('Keep control of the session','Power Dialer and Campaigns come with the Campaigns & Power Dialer add-on. It is a guided calling workflow, not a promise of predictive or parallel calling.',['Review each lead before contacting','Record the result after a conversation','Respect opt-outs immediately'])]),
('scripts','Call Scripts','Give your team a useful starting point.','Keep a consistent introduction, qualification questions and next steps available while handling calls.', [('Prepare a conversation, not a monologue','Write a short opening and the facts your team must not miss. Use questions that leave room for the customer to respond.',['Opening and identity','Reason for the call','A clear next action']),('Keep scripts accurate','Review scripts when offers or contact details change. Do not impersonate another organisation or make promises your business cannot meet.',['Use approved product information','Keep pricing consistent','Record genuine customer requirements'])]),
('dispositions','Call Outcomes','Make the next action obvious.','Record a useful outcome after each Power Dialer conversation so that the team knows what happened.', [('Choose a meaningful result','Distinguish a connected conversation from a busy line, no answer or failed attempt.',['Interested or not interested','Callback requested','Answered, busy or no answer']),('Pair outcomes with notes','A short note can explain why a follow-up is needed. Keep notes factual and limited to what the business needs.',['Record the requested next step','Avoid unnecessary personal information','Keep the record associated with the correct lead'])]),
('follow-ups','Follow-up Workflow','Leave the next conversation better prepared.','Use lead statuses, follow-up details and call notes to keep track of customers who need another conversation.', [('Keep context close','Record the requested callback information and review it before dialing again.',['Lead-level follow-up details','Call notes','Callback outcomes']),('No reminder promise','Automated reminders and calendar integrations are not advertised as current included features. Discuss any scheduling requirements during your demo.',['Review callbacks with your team','Confirm the customer timezone','Request advanced scheduling separately'])]),
('crm','CRM Integration','Your leads and calls, in the same workflow.','Manage lead information, upload eligible CSV records and connect customer context with the next call.', [('Build a useful lead list','Keep names, international phone numbers and relevant notes together. Search and update records as work progresses.',['Lead search and editing','CSV import workflow','Consent and Do Not Call flags']),('Move from a record to a conversation','Select eligible CRM leads for your Power Dialer queue and record what happened after each attempt.',['Select leads for a queue','Track statuses and notes','Keep consent records accurate'])]),
('dashboard','Call Analytics','Know where your calling time goes.','Review call volume, outcomes and average recorded talk time with daily, weekly and monthly views.', [('A clearer view of activity','Use calls over time to understand your team workflow, not to manufacture performance claims.',['Time-based call counts','Answer rate','Average recorded talk time']),('Look at the underlying records','A chart is only as good as the recorded call data. Use Call Logs to review individual results.',['Incoming and outgoing history','Selected time periods','No live-agent surveillance feature advertised'])]),
('call-logs','Call Logs','Every attempt deserves context.','Review your recent calling activity, filter by direction and see the available status and duration.', [('Find the conversation','Separate incoming, outgoing and missed activity rather than treating every attempt as a connected call.',['Direction filters','Call status','Recorded duration']),('Continue the workflow','Use an available number in the calling workflow and check the customer record before making a follow-up.',['Contact context','Review before redialing','Respect Do Not Call requests'])]),
('contacts','Contacts & Notes','Keep the details that make calls useful.','Save customer contacts and make notes that help your team start the next conversation with context.', [('A practical address book','Keep contact details organised and verify the international phone number format.',['Saved contacts','Names and numbers','Calling workflow']),('Separate contacts from lead imports','CRM CSV imports and saved contacts are different workflows. Use the relevant screen for the task.',['Import eligible leads through CRM','Avoid unnecessary sensitive data','Keep customer details current'])]),
('do-not-call','Do Not Call','An opt-out should change the workflow.','Record Do Not Call preferences in CRM and keep ineligible leads out of Power Dialer authorisation.', [('Respect the record','Do not label a lead as opted in without evidence. Update preferences promptly when someone asks not to be called.',['Consent flags','Do Not Call marking','Checks before a queue call']),('Controls do not replace your duties','A software flag does not replace applicable calling rules or external preference registers. Your business remains responsible for lawful outreach.',['Document permission','Maintain accurate lists','Train users on handling opt-outs'])]),
('search','Finding Records','Less hunting. More context.','Use CRM search and Call Logs filters to find the record you need before your next conversation.', [('Choose the right screen','Look up a lead in CRM or narrow recent activity by call direction.',['CRM search','Call Logs filters','Contacts view']),('Be precise about current features','A single universal search across the entire dialer is not advertised. Website search searches our public pages only.',['Search guides on this site','Review product capabilities','Ask about requirements in a demo'])]),
]
