for slug,label,headline,use,steps in solution_specs:
    add('/solutions/'+slug+'/',headline,'Solutions / '+label,'Use Dialnytics to '+use+'. Calling, CRM and voicemail are included; add recording, Campaigns & Power Dialer or SMS when you need them.', [('A practical workflow for '+label.lower(),'Use the dialer alongside your existing business processes.',steps),('Pay for what your team uses','Choose a destination plan and the number of users, then add only the extras you need. Prices include taxes and there is no setup fee.',['Dedicated caller ID and CRM','Optional recording, Power Dialer and SMS','Call Logs and analytics']),('See the workflow before you decide','Book a 15-minute guided demo. We will confirm the timing on WhatsApp. There is no free trial and this is not an automatic account creation form.',['Ask about your specific workflow','Confirm destination requirements','Choose the plan that fits'])],group='solutions',label=label)
