FAQ=[
('Do I need any hardware or a phone line?','No. Dialnytics runs in your web browser on a computer or phone. You need a reliable internet connection and, ideally, a headset. There is no desk phone, SIM card or app to install.'),
('Which countries can I get numbers for?','USA and Canada, the United Kingdom, Australia and Japan have their own plans. There is also a Global plan, a UK-to-Europe plan and quotes for European local numbers or a custom mix. Number availability is confirmed before you pay.'),
('How much does it cost?','PLACEHOLDER_COST'),
('Is calling really unlimited?','There is no fixed monthly minute cap for calls to the destinations in your chosen plan. It is for normal, lawful business calling, not every possible route or premium number. See the unlimited calling page for details.'),
('Can I send text messages?','Yes. SMS texting is an optional add-on with 300 texts per user each month, sent from your business number. A one-time registration fee covers the business texting registration (A2P 10DLC for US numbers). Texting starts once the registration is approved.'),
('Is voicemail included?','Yes. Every plan includes voicemail. Callers can leave a message when you are away and you can play it back in the dialer.'),
('What are add-ons and do I need them?','PLACEHOLDER_ADDONS'),
('How do payment and account approval work?','Send your request, then our team confirms your number and details on WhatsApp. You pay by Bank Transfer, USDT or a secure Stripe card link. We review the account, set it up and activate it, usually 10-15 minutes after payment is confirmed, 24/7.'),
('How does USA and Canada team pricing work?','One user is $22 per month. Two users are $38 total per month. Three or more users are $15 per user per month. For example, five users cost $75 per month.'),
('Do you offer a free trial?','No. You can watch the product tour or book a 15-minute guided demo instead. The team will confirm your demo timing on WhatsApp.'),
('When is customer support available?','Monday-Friday, 3 PM to 3 AM the following morning, Pakistan Time (PKT / UTC+5). The Friday shift ends on Saturday at 3 AM. Account activation availability is separate from support hours.'),
('Can I choose a particular phone number?','Tell us your preferred country, area or number type. Number availability and verification requirements are confirmed by the team. Submitting a request does not reserve a number.'),
('Is AI included?','Not yet. AI insights (call summaries and transcripts), live captions and Floating Phone are coming soon. AI insights will be an optional add-on. You cannot order or pay for them today.'),
('Where do existing customers sign in?','Use Client Login to open dialnytics.co.uk. This marketing website and its enquiries admin are separate from your calling account.'),
('What happens after I submit a form?','Your request is saved with a reference number. You can then open a prepared WhatsApp message. Your saved request remains available to the team even if you do not send the WhatsApp message.'),
('What is your refund policy?','Final refund and cancellation terms have not yet been published. Request the applicable written terms before making payment. This site does not promise either automatic refunds or a blanket no-refund policy.'),
]

add('/about/','Built around the next conversation.','About Dialnytics','Dialnytics brings business calling and lead workflows together, with straightforward country pricing and a human setup process.', [('Who operates Dialnytics','Dialnytics is operated by PRIME MSM LIMITED. Use the company and contact details below to get in touch.',['Company number: '+BUSINESS['company_number'],'Registered office: '+BUSINESS['address'],'Business contact: '+BUSINESS['email']]),('Two websites. Two different jobs.','dialnytics.uk explains plans, collects requests and helps you choose a service. Existing customers use dialnytics.co.uk for the actual dialer.',['Marketing enquiries are not calling accounts','Payment is arranged with the team','No change to the existing dialer from this website']),('A clear offer','Payable prices should be easy to understand. Every plan has one per-user price with taxes included, and the few optional add-ons are listed with their price.',['No setup charge','Taxes included','15-minute guided demos, no free trial'])])
add('/how-it-works/','From your plan to your first call.','Getting started','Choose a plan, pay, let us review and set up your account, then start calling.', [('01 / Choose your plan','Pick your country, the number of users and any add-ons. The calculator shows the monthly total with taxes included. Send the request and we confirm your number on WhatsApp.',['Choose a destination','Set your team size','Add recording, Power Dialer or SMS if needed']),('02 / Pay','Pay by Bank Transfer, USDT or a secure Stripe card link. We send the payment details on WhatsApp. This website never asks for card details.',['Taxes included in the price','No setup fee','Ask for the final refund terms in writing']),('03 / Account review & setup','We check your business details, assign your number and set up your users. Texting needs a business registration first, which we submit for you.',['Activation 24/7','Usually 10-15 minutes after payment is confirmed','SMS switched on after registration is approved']),('04 / Start calling','You receive your login for dialnytics.co.uk. Test your headset and make your first call from the browser.',['Receive your login details','Test your headset and browser','Support: Mon-Fri, 3 PM-3 AM PKT'])])
add('/payments/','Choose how you would like to pay.','Payments','Payments are arranged manually through our team. Sending an enquiry is not a payment and does not activate an account.', [('Bank Transfer','Request current beneficiary details from the team. Check the business identity before making a transfer.',['Payment instructions provided securely','No bank details invented on this website','Payment must be confirmed before activation']),('USDT','Confirm the wallet address, blockchain network and payable amount directly with the authorised team before sending.',['No wallet address published here','Do not assume networks are interchangeable','Never send a wallet recovery phrase']),('Credit / Debit Card via Stripe','The team can provide an appropriate secure payment link. Enter card information only on the genuine payment provider page.',['Card payment preference recorded','No card number or CVV collected here','No payment success claimed by this website'])])
add('/system-requirements/','Get your browser ready to call.','Browser guide','Use an up-to-date browser, a working microphone and a reliable connection. A short test before a calling session is better than guessing.', [('Before you start','Check microphone permissions and your selected input/output devices. Use a headset where practical.',['Allow the dialer to use the microphone','Check the correct speaker and mic are selected','Keep the browser and operating system updated']),('A connection that stays with you','A stable connection matters for live audio. Confirm that your organisation allows browser calling traffic.',['Avoid changing networks mid-call','Ask IT about blocked traffic','Test an incoming and outgoing call']),('Mobile and background behaviour','This marketing website adapts to screen size. Browser calling in the separate dialer can still be affected by device permissions, sleep and background restrictions.',['Keep the dialer foregrounded during tests','Do not treat a closed tab as an available phone','Discuss your exact device workflow in a demo'])])
add('/product/overview/','One workspace. Every conversation in context.','Product overview','Start with the tools every plan includes, add the extras your team needs, then see the workflow in a guided demo.', [('Included in every plan','Unlimited calling in your selected plan destinations, a dedicated caller ID, CRM, call logs and voicemail.',['Browser calling','Dedicated business identity','Voicemail included']),('Optional add-ons','Call recording, Campaigns & Power Dialer and SMS texting can be added per user. Each add-on has one clear monthly price.',['Call recording','Campaigns & Power Dialer','SMS texting']),('Coming soon','AI summaries/transcripts, live captions and Floating Phone are planned, not live. They cannot be ordered yet.',['Nothing to pay for unavailable features','No fabricated testimonials','No self-service payment or automatic user creation'])],group='overview')

