guides=[
('first-call','Making your first call','Confirm the active account, open the dialer and test your audio.', [('Check your setup','Sign in at dialnytics.co.uk using the account details supplied after activation. Confirm the displayed caller ID.',['Allow microphone access','Select your headset','Use a genuine test number with permission']),('Place and review','Enter an international number, place the call and review the recorded result in Call Logs.',['Check the destination format','Review call status','Contact support with the time and reference if needed'])]),
('crm-import','Preparing a CRM CSV','Good imports start with clear column names and valid international numbers.', [('Prepare your fields','The current CRM workflow uses name, phone, email, consent and do_not_call fields. Email is optional.',['Use international phone numbers starting with +','Use accurate consent records','Keep headers consistent']),('Do not invent permission','An affirmative consent value is not a substitute for actual permission. A Do Not Call lead should not be added to a calling queue.',['Review consent before upload','Check skipped rows','Avoid uploading unnecessary sensitive details'])]),
('power-dialer','Working with a Power Dialer queue','Start with a selected, eligible list and keep control of the session.', [('Create the queue','Select appropriate CRM leads and your calling mode. Check the next lead before starting.',['Use the Start control','Pause or stop when needed','Skip a pending number when appropriate']),('Finish the record','Save call notes and choose an outcome before moving to the next task.',['Keep notes relevant','Mark opt-outs immediately','Review remaining leads before continuing'])]),
('recording','Recording responsibly','Use the recording feature only after checking the necessary permission and notice requirements.', [('Prepare your process','Tell your team when recording is appropriate. Make sure access and storage arrangements fit your business.',['Inform participants where required','Avoid recording sensitive information unnecessarily','Confirm retention arrangements']),('Review the controls','Ask for a recording demonstration during your guided demo so that the team understands how it works.',['Check recording is enabled','Review available files','Follow your own approved retention process'])]),
('call-history','Understanding call history','An attempted call is not always an answered conversation.', [('Read the status','Compare direction, status and duration together. A failed or missed call may have no talk time.',['Incoming versus outgoing','Connected versus attempted','Recorded talk time']),('Use the right period','Select Today, This Week or This Month to review activity in the dashboard.',['Check the selected dates','Review individual call records','Do not interpret sample tour data as live activity'])]),
('contacts','Keeping contacts organised','Use a consistent name and international number format.', [('Create useful records','Record only the details your team needs for the conversation.',['Keep names readable','Check numbers before dialing','Review outdated information']),('Use the right workflow','Use saved contacts for the address book and CRM for lead statuses, imports and queue selection.',['Search before adding duplicates','Respect opt-outs','Keep relevant notes'])]),
('billing','Plans, payment and activation','Understand what is payable before sending money.', [('Your listed plan price','Listed prices include taxes. There is no setup fee. Optional add-ons are shown with their own price before you send a request.',['All published amounts are USD monthly','USA/Canada team pricing is automatic','Custom quotes are confirmed in writing']),('Confirm before payment','The enquiry does not collect payment. The team confirms the number, requirements and applicable written terms.',['Bank Transfer, USDT or Stripe preference','Activation after confirmed payment','Request final refund terms before paying'])]),
('incoming','Preparing for incoming calls','Keep the browser dialer connected when customers may call.', [('Ready to answer','Check the assigned number and audio devices before your shift.',['Keep microphone permission enabled','Check browser connectivity','Test a callback with permission']),('Missed and private calls','Caller information depends on what the network supplies. Do not assume that every incoming call will display a usable callback number.',['Review Call Logs','Do not redial placeholder identities','Check Voicemails for missed callers'])]),
('notes','Writing useful call notes','A short factual note is easier to use than a long transcript.', [('What to record','Capture the request, agreed action and relevant timing.',['Customer requirement','Next action owner','Requested follow-up']),('What not to record','Do not store payment security codes, passwords or unnecessary identity documents in call notes.',['Keep the note relevant','Limit access','Follow your business retention process'])]),
('dnc','Handling opt-outs','A Do Not Call request should be reflected in the record promptly.', [('Update the lead','Use the CRM consent and Do Not Call fields accurately.',['Record the request','Avoid creating another duplicate lead','Do not add ineligible records to queues']),('Check before calling','Apply your own regulatory and preference-list checks as well as the software workflow.',['Review the current record','Train the team','Escalate complaints to support'])]),
('audio','Troubleshooting browser audio','Start with device permissions before changing account settings.', [('Check the basics','Confirm the microphone is not blocked, your headset is selected and the output is not muted.',['Browser permission','Operating system device','Headset volume']),('Share useful evidence','Send support the time, your account email and the visible error. Never send API keys or passwords.',['Describe incoming or outgoing','Include the relevant status','Use the support form or WhatsApp'])]),
('account-access','Signing in safely','Keep your credentials private and use the correct website.', [('Use Client Login','Existing dialer accounts are at dialnytics.co.uk. Marketing requests and the marketing admin are on dialnytics.uk.',['Use the correct domain','Do not share passwords','Report unusual access']),('Need help?','Send a support request with your account email. Do not include a password or recovery code.',['Include a clear description','Give the time of the problem','Support hours are shown on the contact page'])]),
]
