# ---------------------------------------------------------------- price text that follows admin-managed prices
def _usa_pricing_text():
    from .catalog import price_view
    p = price_view()
    return (f"One user is ${p['usa_1']} per month. Two users are ${p['usa_2']} total per month. "
            f"Three or more users are ${p['usa_per']} per user per month. For example, five users cost ${p['usa_5_total']} per month.")

def _plans_text():
    from .catalog import price_view
    p = price_view()
    return (f"Prices are in US dollars per month. USA/Canada: one user ${p['usa_1']}, two users ${p['usa_2']} total, "
            f"three or more ${p['usa_per']} per user. UK ${p['uk']}, Australia ${p['australia']}, Japan ${p['japan']} "
            f"and Global ${p['global']} per user. Prices include taxes. Setup is free. Optional add-ons per user per month: "
            f"Call recording ${p['addon_recording']}, Campaigns & Power Dialer ${p['addon_campaigns']}, SMS texting ${p['addon_sms']} "
            f"(plus a one-time ${p['sms_setup']} registration).")

def _cost_text():
    from .catalog import price_view
    p = price_view()
    return (f"Plans start from ${p['from']} per user per month, with taxes included and no setup fee. USA & Canada is "
            f"${p['usa_1']} for one user, ${p['usa_2']} for two, then ${p['usa_per']} per user. UK is ${p['uk']}, Australia "
            f"${p['australia']} and Japan ${p['japan']} per user. Use the calculator to add users and add-ons.")

def _addons_text():
    from .catalog import price_view
    p = price_view()
    return (f"Every plan already includes calling, your number, CRM, call logs and voicemail. Add-ons are optional extras, per user "
            f"per month: Call recording ${p['addon_recording']}, Campaigns & Power Dialer ${p['addon_campaigns']} and SMS texting "
            f"${p['addon_sms']} (300 texts, plus ${p['sms_setup']} one-time registration). AI insights (${p['addon_ai']}) is coming soon.")

def refresh_price_text():
    """Rewrite the few content strings that quote prices (FAQ + billing policy) after prices change."""
    for i, (q, _) in enumerate(FAQ):
        if q == 'How does USA and Canada team pricing work?':
            FAQ[i] = (q, _usa_pricing_text())
        elif q == 'How much does it cost?':
            FAQ[i] = (q, _cost_text())
        elif q == 'What are add-ons and do I need them?':
            FAQ[i] = (q, _addons_text())
    page = PAGES.get('/legal/billing-refund-cancellation/')
    if page:
        for section in page['sections']:
            if section['title'] == 'Monthly plans':
                section['text'] = _plans_text()

refresh_price_text()
